    /** 统一为筛选按钮配置 18dp 描边 SVG 矢量图标，避免 Unicode 图标跨设备差异。 */
    private void setButtonIcon(Button button,int resId,boolean selected){
        Drawable icon=getDrawable(resId);
        if(icon==null)return;
        icon.mutate().setTint(selected?Color.WHITE:GREEN);
        icon.setBounds(0,0,dp(17),dp(17));
        button.setCompoundDrawables(icon,null,null,null);
        button.setCompoundDrawablePadding(dp(6));
    }

