    private String wrapTitle(String title){return title.length()>4?title.substring(0,3)+"\n"+title.substring(3):title;}
    private void loadCover(JSONObject item,ImageView target){loadCover(item,target,0);}
    private void loadCover(JSONObject item,ImageView target,int attempt){
        String first=Catalog.secureUrl(item.optString("image")),backup=Catalog.secureUrl(item.optString("imageBackup"));String asset=item.optString("imageAsset");String identity=item.optString("id")+first+backup+asset;target.setTag(identity);target.setContentDescription(item.optString("title")+" · 封面加载中");if(first.isEmpty()&&backup.isEmpty()&&asset.isEmpty()){target.setContentDescription(item.optString("title")+" · 来源未提供封面");return;}
        Bitmap cached=covers.get(identity);if(cached!=null){target.setImageBitmap(cached);target.setContentDescription(item.optString("title")+" · 封面已加载");return;}
        images.execute(()->{Bitmap loaded=null;boolean transientFailure=false;if(!asset.isEmpty()){try{loaded=CoverLoader.local(this,asset);}catch(Exception failure){if(BuildConfig.DEBUG)android.util.Log.w("ZhigengCover","离线封面加载失败",failure);}}for(String url:new String[]{first,backup}){if(loaded!=null)break;if(url.isEmpty())continue;try{loaded=CoverLoader.download(url);break;}catch(Exception failure){if(failure instanceof UnknownHostException||failure instanceof SocketTimeoutException||failure instanceof ConnectException)transientFailure=true;if(BuildConfig.DEBUG)android.util.Log.w("ZhigengCover",Uri.parse(url).getHost()+" "+failure.getClass().getSimpleName()+": "+failure.getMessage());}}Bitmap got=loaded;boolean retryable=transientFailure;if(got!=null)covers.put(identity,got);runOnUiThread(()->{if(isFinishing()||isDestroyed()||!identity.equals(target.getTag()))return;if(got!=null){target.setImageBitmap(got);target.setContentDescription(item.optString("title")+" · 封面已加载");}else if(retryable&&attempt<2){target.setContentDescription(item.optString("title")+" · 等待网络后重试封面");target.postDelayed(()->{if(!isFinishing()&&!isDestroyed()&&target.isAttachedToWindow()&&identity.equals(target.getTag()))loadCover(item,target,attempt+1);},1800L*(attempt+1));}else{target.setContentDescription(item.optString("title")+" · 封面加载失败，点击重试");target.setOnClickListener(v->{target.setOnClickListener(null);loadCover(item,target);});}});});
    }
    private JSONObject saved(){try{return new JSONObject(prefs.getString("shelf","{}"));}catch(Exception e){return new JSONObject();}}
