    private void downloadBook(JSONObject item,String link){
        java.util.concurrent.atomic.AtomicBoolean cancelled=new java.util.concurrent.atomic.AtomicBoolean(false);activeDownload=cancelled;LinearLayout box=col();box.setPadding(dp(22),dp(15),dp(22),dp(15));TextView info=label("正在连接下载…",14,INK);add(box,info,0);ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);add(box,progress,15);AlertDialog d=new AlertDialog.Builder(this).setTitle(item.optString("title")).setView(box).setNegativeButton("取消",(a,b)->cancelled.set(true)).setCancelable(false).create();downloadProgress=d;d.show();jobs.execute(()->{try{String format=DownloadPolicy.extension(item.optString("format"));File file=BookDownloader.download(this,link,format,catalog.downloadHeaders(link),cancelled,(bytes,total)->runOnUiThread(()->{if(isFinishing()||isDestroyed())return;progress.setIndeterminate(total<=0);if(total>0)progress.setProgress((int)(bytes*100/total));info.setText(String.format(Locale.ROOT,"已下载 %.1f MB",bytes/1048576.0)+(total>0?" · "+(bytes*100/total)+"%":""));}));JSONObject local=new JSONObject(item.toString());local.put("localUri",Uri.fromFile(file).toString()).put("format",format);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;d.dismiss();addToShelf(local,"想读");saveBookToPhone(local);});}catch(Exception e){runOnUiThread(()->{if(isFinishing()||isDestroyed())return;d.dismiss();toast(e.getMessage()==null?"下载失败，请重试":e.getMessage());});}});
    }
    private void saveBookToPhone(JSONObject item){
        if(Build.VERSION.SDK_INT<29){saveBookAs(item);return;}
        toast("正在保存到手机…");jobs.execute(()->{try{
            LocalBookStore.SavedFile copy=LocalBookStore.publish(this,Uri.parse(item.optString("localUri")),item.optString("title"),item.optString("format"),new java.util.concurrent.atomic.AtomicBoolean(false));
            runOnUiThread(()->{if(isFinishing()||isDestroyed())return;showPhoneCopy(item,copy.uri,"下载/知更/"+copy.name);});
        }catch(Exception error){runOnUiThread(()->{if(isFinishing()||isDestroyed())return;new AlertDialog.Builder(this).setTitle("书架中的图书已保留").setMessage("手机本地副本未保存完成，请选择其他文件夹重试。\n"+Objects.toString(error.getMessage(),""))
            .setNegativeButton("稍后",null).setNeutralButton("立即阅读",(d,w)->readLocal(item)).setPositiveButton("选择保存位置",(d,w)->saveBookAs(item)).show();});}});
    }
    private void showPhoneCopy(JSONObject item,Uri uri,String location){
        new AlertDialog.Builder(this).setTitle("已保存到手机本地").setMessage(item.optString("title")+"\n\n保存位置："+location+"\n可在手机文件管理器中找到；移出书架不会删除这份文件。")
            .setPositiveButton("立即阅读",(d,w)->readLocal(item)).setNegativeButton("打开文件",(d,w)->openPhoneCopy(uri,item.optString("format")))
            .setNeutralButton("另存到…",(d,w)->saveBookAs(item)).show();
    }
    private void openPhoneCopy(Uri uri,String format){
        Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,BookFileNames.mimeType(format)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
        intent.setClipData(ClipData.newRawUri("图书文件",uri));
        try{startActivity(Intent.createChooser(intent,"选择打开图书的应用"));}catch(ActivityNotFoundException|SecurityException error){toast("手机上暂无可打开此格式的应用，请在知更书架阅读");}
    }
    private void saveBookAs(JSONObject item){
        if(!prefs.edit().putString("pendingPhoneExport",item.toString()).commit()){toast("暂时无法准备另存，请稍后重试");return;}
        Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(BookFileNames.mimeType(item.optString("format")))
            .putExtra(Intent.EXTRA_TITLE,BookFileNames.fileName(item.optString("title"),item.optString("format")));
        try{startActivityForResult(intent,EXPORT);}catch(ActivityNotFoundException error){prefs.edit().remove("pendingPhoneExport").apply();toast("未找到系统文件管理器，书架中的文件仍可阅读");}
    }
    private void exportBookResult(int result,Intent data){
        String pending=prefs.getString("pendingPhoneExport","");prefs.edit().remove("pendingPhoneExport").apply();
        if(result!=RESULT_OK||data==null||data.getData()==null||pending.isEmpty())return;
        Uri target=data.getData();try{getContentResolver().takePersistableUriPermission(target,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(Exception ignored){}
        jobs.execute(()->{try{JSONObject item=new JSONObject(pending);LocalBookStore.copy(this,Uri.parse(item.optString("localUri")),target,new java.util.concurrent.atomic.AtomicBoolean(false));
            String display=BookFileNames.fileName(item.optString("title"),item.optString("format"));try(android.database.Cursor cursor=getContentResolver().query(target,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())display=cursor.getString(0);}catch(Exception ignored){}final String name=display;
            runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())showPhoneCopy(item,target,"你选择的文件夹 / "+name);});
        }catch(Exception error){try{android.provider.DocumentsContract.deleteDocument(getContentResolver(),target);}catch(Exception ignored){}runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())toast("未能完成另存，书架中的图书仍保留，请重新选择保存位置");});}});
    }
    private void shelf(){
        add(body,label("PERSONAL LIBRARY",10,GREEN),15);add(body,heading("留一点时间，给喜欢。",26),10);add(body,label("想读、在读、已读，和你自己的电子书。",13,MUTED),8);Button imp=button("＋ 导入 TXT / EPUB / PDF",true);add(body,imp,20);imp.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"text/plain","application/epub+zip","application/pdf"});startActivityForResult(i,IMPORT);});
        JSONObject s=saved();if(s.length()==0){add(body,label("书架还是空的。搜索到喜欢的作品后，点开详情收藏。",15,MUTED),30);return;}
        Iterator<String> keys=s.keys();while(keys.hasNext()){String key=keys.next();JSONObject item=s.optJSONObject(key);if(item==null)continue;LinearLayout card=col();card.setPadding(dp(16),dp(15),dp(16),dp(15));card.setBackground(background(Color.WHITE,15));add(card,heading(item.optString("title"),17),0);add(card,label(item.optString("readingStatus","想读")+" · "+item.optString("author")+" · "+(item.has("localUri")?"本地图书":item.optString("source")),12,GREEN),7);card.setOnClickListener(v->details(item));card.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("移出书架？").setMessage(item.optString("title")).setNegativeButton("取消",null).setPositiveButton("移除",(d,w)->{JSONObject entries=saved();entries.remove(key);save(entries);render();}).show();return true;});add(body,card,12);}
        add(body,label("长按作品可移出书架。本地文件仍由你自己保留。",11,MUTED),18);
    }
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==BOOKORBIT){if(result==RESULT_OK&&data!=null)try{JSONObject item=new JSONObject(data.getStringExtra("downloadedBook"));addToShelf(item,"想读");page="shelf";render();saveBookToPhone(item);}catch(Exception error){toast("无法添加下载到书架，请重试");}return;}if(request==EXPORT){exportBookResult(result,data);return;}if(request!=IMPORT||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}
        String name="电子书";try(android.database.Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}catch(Exception ignored){}
        String lower=name.toLowerCase(Locale.ROOT);if(!lower.endsWith(".txt")&&!lower.endsWith(".epub")&&!lower.endsWith(".pdf")){toast("请选择 TXT、EPUB 或 PDF 文件");return;}
        try{JSONObject item=new JSONObject().put("id","local:"+uri).put("title",name).put("type","book").put("author","").put("source","本地图书").put("localUri",uri.toString()).put("format",lower.endsWith(".pdf")?"pdf":lower.endsWith(".epub")?"epub":"txt");addToShelf(item,"想读");render();}catch(Exception e){toast("导入失败");}
    }
    private void readLocal(JSONObject item){
        Uri uri=Uri.parse(item.optString("localUri"));if(item.optString("format").equals("pdf")){startActivity(new Intent(this,PdfActivity.class).putExtra("uri",uri.toString()));return;}
        if(!item.optString("format").equals("txt")&&!item.optString("format").equals("epub")){toast("文件已保存；当前内置阅读支持 EPUB、TXT 和 PDF。");return;}
        Intent i=new Intent(this,ReaderActivity.class);i.putExtra("uri",uri.toString());i.putExtra("title",item.optString("title"));i.putExtra("format",item.optString("format"));startActivity(i);
    }
    private void readerLicenses(){StringBuilder value=new StringBuilder("Readium Kotlin 3.1.0 · BSD-3-Clause\nhttps://github.com/readium/kotlin-toolkit\n\n阅读字体：基于 Noto Serif SC 的本地子集 · SIL OFL 1.1\nhttps://github.com/google/fonts/tree/main/ofl/notoserifsc\n\n");for(String file:new String[]{"readium-BSD-3-Clause.txt","reader-font-OFL.txt","jsoup-MIT.txt"})try(java.io.InputStream in=getAssets().open(file)){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);value.append(out.toString("UTF-8")).append("\n\n");}catch(Exception ignored){}TextView text=label(value.toString(),12,INK);text.setTextIsSelectable(true);text.setPadding(dp(20),dp(20),dp(20),dp(20));ScrollView view=new ScrollView(this);view.addView(text);new AlertDialog.Builder(this).setTitle("阅读器与字体许可").setView(view).setPositiveButton("关闭",null).show();}
