    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("page",page);state.putString("type",query.type);state.putString("query",query.text);state.putString("provider",query.provider);state.putString("region",query.region);state.putString("year",query.year);state.putString("sort",query.sort);state.putString("rankSource",query.rankSource);state.putInt("resultPage",query.page);state.putBoolean("publicCatalog",query.publicCatalog);}
